// Standalone BetterBLOX settings page.
//
// Renders entirely from the shared settings catalog and talks to
// chrome.storage.local via storageManager — it has ZERO dependency on the
// Roblox DOM, so it can't go blank when Roblox changes its markup (the failure
// mode of the old in-page settings UI). Settings written here are picked up by
// the content scripts the next time a Roblox page loads.

import { SETTINGS_PAGES, SETTINGS_CATALOG } from "../betterblox-frontend/ui/settings/catalog.js";
import { storageManager } from "../betterblox-frontend/core/storageManager.js";

const browserAPI = typeof browser === "undefined" ? chrome : browser;

const sidebar = document.getElementById("sidebar");
const content = document.getElementById("content");
const toastEl = document.getElementById("toast");
const resetBtn = document.getElementById("reset-btn");
const versionBadge = document.getElementById("version-badge");

const VALID_PAGES = new Set(SETTINGS_PAGES.map((p) => p.id));
let activePage = "info";
let toastTimer = null;
// Bumped on every navigate(); an async render bails if a newer one started,
// so rapid section switches can't leave the sidebar and content out of sync.
let renderToken = 0;

function currentPageFromHash() {
  const hash = (window.location.hash || "").replace(/^#/, "");
  return VALID_PAGES.has(hash) ? hash : "info";
}

function showToast(message = "Saved") {
  toastEl.textContent = message;
  toastEl.classList.add("show");
  if (toastTimer) clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.remove("show"), 1600);
}

function renderSidebar() {
  sidebar.replaceChildren();
  for (const page of SETTINGS_PAGES) {
    const btn = document.createElement("button");
    btn.className = "nav-item" + (page.id === activePage ? " active" : "");
    btn.textContent = page.title;
    btn.setAttribute("aria-current", page.id === activePage ? "page" : "false");
    btn.addEventListener("click", () => {
      if (window.location.hash !== `#${page.id}`) {
        window.location.hash = page.id;
      } else {
        navigate(page.id);
      }
    });
    sidebar.appendChild(btn);
  }
}

function createToggle(setting, value) {
  const label = document.createElement("label");
  label.className = "switch";

  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = !!value;
  input.setAttribute("aria-label", setting.title);
  input.addEventListener("change", async () => {
    await storageManager.setSettings(setting.id, input.checked);
    showToast(`${setting.title} ${input.checked ? "on" : "off"}`);
  });

  const slider = document.createElement("span");
  slider.className = "slider";

  label.appendChild(input);
  label.appendChild(slider);
  return label;
}

function createDropdown(setting, value) {
  const select = document.createElement("select");
  select.className = "field";
  select.setAttribute("aria-label", setting.title);
  for (const opt of setting.options || []) {
    const o = document.createElement("option");
    o.value = opt.value;
    o.textContent = opt.label;
    select.appendChild(o);
  }
  if (value !== undefined && value !== null) select.value = value;
  select.addEventListener("change", async () => {
    await storageManager.setSettings(setting.id, select.value);
    showToast(`${setting.title} updated`);
  });
  return select;
}

function createInput(setting, value) {
  const input = document.createElement("input");
  input.type = "text";
  input.className = "field";
  input.setAttribute("aria-label", setting.title);
  input.placeholder = setting.placeholder || "";
  input.value = value ?? "";
  if (setting.maxLength) input.maxLength = setting.maxLength;
  input.autocomplete = "off";
  input.spellcheck = false;
  let saveTimer = null;
  input.addEventListener("input", () => {
    if (saveTimer) clearTimeout(saveTimer);
    saveTimer = setTimeout(async () => {
      await storageManager.setSettings(setting.id, input.value);
      showToast(`${setting.title} saved`);
    }, 400);
  });
  return input;
}

function buildControl(setting, value) {
  switch (setting.type) {
    case "toggle":
      return createToggle(setting, value);
    case "dropdown":
      return createDropdown(setting, value);
    case "input":
      return createInput(setting, value);
    default:
      return null;
  }
}

async function renderSettingsPage(pageId, token) {
  const settings = SETTINGS_CATALOG[pageId] || [];
  const pageMeta = SETTINGS_PAGES.find((p) => p.id === pageId);

  const panel = document.createElement("section");
  panel.className = "panel";

  const head = document.createElement("div");
  head.className = "panel-head";
  const h2 = document.createElement("h2");
  h2.textContent = pageMeta ? pageMeta.title : pageId;
  head.appendChild(h2);
  panel.appendChild(head);

  if (settings.length === 0) {
    const p = document.createElement("p");
    p.className = "info-card";
    p.textContent = "No settings in this section yet.";
    panel.appendChild(p);
  }

  for (const setting of settings) {
    const value = await storageManager.getSettings(setting.id, setting.defaultValue);

    const row = document.createElement("div");
    row.className = "setting-row";

    const text = document.createElement("div");
    text.className = "setting-text";

    const title = document.createElement("div");
    title.className = "title";
    const titleText = document.createElement("span");
    titleText.textContent = setting.title;
    title.appendChild(titleText);
    if (setting.isBeta) {
      const beta = document.createElement("span");
      beta.className = "beta-tag";
      beta.textContent = "Beta";
      title.appendChild(beta);
    }
    text.appendChild(title);

    if (setting.description) {
      const desc = document.createElement("div");
      desc.className = "desc";
      desc.textContent = setting.description;
      text.appendChild(desc);
    }

    const control = document.createElement("div");
    control.className = "control";
    const el = buildControl(setting, value);
    if (el) control.appendChild(el);

    row.appendChild(text);
    row.appendChild(control);
    panel.appendChild(row);
  }

  // A newer navigate() started while we awaited storage reads — drop this stale
  // render so it can't clobber the content the user actually selected.
  if (token !== renderToken) return;
  content.replaceChildren(panel);

  const note = document.createElement("div");
  note.className = "reload-note";
  note.textContent = "↻ Reload your open Roblox tabs for changes to take effect.";
  content.appendChild(note);
}

function renderInfoPage() {
  const version = browserAPI.runtime.getManifest().version;

  const panel = document.createElement("section");
  panel.className = "panel";
  panel.innerHTML = `
    <div class="panel-head">
      <h2>Better Roblox Extension</h2>
      <p>Version ${version} • Beta Release</p>
    </div>
    <div class="info-card">
      <p>Welcome to BetterBLOX! This is the standalone settings page — it works
      anywhere, independently of the Roblox website.</p>
      <div class="callout warn">
        <strong>Heads up:</strong> after installing or changing a setting, give
        the extension a moment and reload any open Roblox tabs. Friends' last-online
        data can take up to 24&nbsp;hours to fully sync.
      </div>
      <p>Use the BetterBLOX website to:</p>
      <ul>
        <li>Get support and troubleshooting help</li>
        <li>Report bugs and technical issues</li>
        <li>Suggest new features and improvements</li>
        <li>Read release notes and updates</li>
      </ul>
      <p>If you're enjoying BetterBLOX, please consider
        <a href="https://chromewebstore.google.com/detail/better-roblox-extension/lplhnhhlblehjmmkcpjbojiaanbpgnpd/reviews" target="_blank" rel="noopener">leaving a 5-star review</a>.
        Your support helps us grow! 🌟</p>
      <p>Visit our <a href="https://betterroblox.com" target="_blank" rel="noopener">official website</a>
        or <a href="https://betterroblox.com/contact" target="_blank" rel="noopener">contact support</a>.</p>
      <p style="color: var(--text-muted); font-size: 0.8rem;">Created with ❤️ by
        <a href="https://github.com/AlloryDante" target="_blank" rel="noopener">Allory Dante</a></p>
    </div>
  `;

  content.replaceChildren(panel);
}

async function navigate(pageId) {
  const token = ++renderToken;
  activePage = VALID_PAGES.has(pageId) ? pageId : "info";
  renderSidebar();
  if (activePage === "info") {
    renderInfoPage();
  } else {
    await renderSettingsPage(activePage, token);
  }
  if (token === renderToken) window.scrollTo({ top: 0 });
}

async function resetAllToDefaults() {
  const ok = window.confirm(
    "Reset all BetterBLOX settings to their default values?"
  );
  if (!ok) return;
  for (const settings of Object.values(SETTINGS_CATALOG)) {
    for (const setting of settings) {
      await storageManager.setSettings(setting.id, setting.defaultValue);
    }
  }
  await navigate(activePage);
  showToast("All settings reset");
}

window.addEventListener("hashchange", () => navigate(currentPageFromHash()));
resetBtn.addEventListener("click", resetAllToDefaults);

versionBadge.textContent = `v${browserAPI.runtime.getManifest().version}`;
navigate(currentPageFromHash());
